// Native HTTP server supports binary uploads across Arduino ESP32 core versions.
class HttpResponse {
 public:
  httpd_req_t* request = nullptr;
  String header(const char* name) {
    size_t n = httpd_req_get_hdr_value_len(request, name);
    if (!n || n > 128) return String();
    char value[129];
    if (httpd_req_get_hdr_value_str(request, name, value, sizeof(value)) != ESP_OK)
      return String();
    return String(value);
  }
  void send(int code, const char* type, const String& body) {
    const char* status = "500 Internal Server Error";
    switch (code) {
      case 200: status = "200 OK"; break;
      case 400: status = "400 Bad Request"; break;
      case 409: status = "409 Conflict"; break;
      case 415: status = "415 Unsupported Media Type"; break;
      case 503: status = "503 Service Unavailable"; break;
    }
    httpd_resp_set_status(request, status);
    httpd_resp_set_type(request, type);
    httpd_resp_send(request, body.c_str(), body.length());
  }
} server;
httpd_handle_t http_server = nullptr;
static bool mdns_ready = false;
static String mdns_ip;
// Heap allocation avoids exhausting the ESP32 static DRAM linker region.
// MALLOC_CAP_INTERNAL | MALLOC_CAP_8BIT uses internal byte-addressable RAM.
static uint8_t* tensor_arena = nullptr;
static tflite::MicroInterpreter* interpreter = nullptr;
static TfLiteTensor* input_tensor = nullptr;
static TfLiteTensor* output_tensor = nullptr;
static bool model_ready = false;
static uint8_t pixel_buffer[INPUT_BYTES];
static size_t received_bytes = 0;
static bool raw_complete = false;
static bool raw_invalid = false;

bool valid_id(const String& value) {
  if (value.length() == 0 || value.length() > 64) return false;
  for (size_t i = 0; i < value.length(); i++) {
    char c = value[i];
    if (!((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
          (c >= '0' && c <= '9') || c == '_' || c == '-')) return false;
  }
  return true;
}

bool init_model() {
  tensor_arena = static_cast<uint8_t*>(heap_caps_malloc(
      TENSOR_ARENA_SIZE, MALLOC_CAP_INTERNAL | MALLOC_CAP_8BIT));
  if (!tensor_arena) {
    Serial.printf("[MODEL] cannot allocate %u bytes; largest free block=%u\n",
                  (unsigned)TENSOR_ARENA_SIZE,
                  (unsigned)heap_caps_get_largest_free_block(MALLOC_CAP_INTERNAL | MALLOC_CAP_8BIT));
    return false;
  }
  const tflite::Model* model = tflite::GetModel(g_parking_model_data);
  if (model->version() != TFLITE_SCHEMA_VERSION) return false;
  // These are the six real ops found in run_gpu01; DELEGATE is a desktop-only op.
  static tflite::MicroMutableOpResolver<6> resolver;
  if (resolver.AddConv2D() != kTfLiteOk || resolver.AddDepthwiseConv2D() != kTfLiteOk ||
      resolver.AddMaxPool2D() != kTfLiteOk || resolver.AddMean() != kTfLiteOk ||
      resolver.AddFullyConnected() != kTfLiteOk || resolver.AddLogistic() != kTfLiteOk) return false;
  static tflite::MicroInterpreter instance(model, resolver, tensor_arena, TENSOR_ARENA_SIZE);
  interpreter = &instance;
  if (interpreter->AllocateTensors() != kTfLiteOk) {
    Serial.printf("[MODEL] AllocateTensors failed with arena=%u; see TFLM log above\n",
                  (unsigned)TENSOR_ARENA_SIZE);
    return false;
  }
  input_tensor = interpreter->input(0);
  output_tensor = interpreter->output(0);
  if (input_tensor->type != kTfLiteInt8 || output_tensor->type != kTfLiteInt8 ||
      input_tensor->dims->size != 4 || input_tensor->dims->data[0] != 1 ||
      input_tensor->dims->data[1] != 64 || input_tensor->dims->data[2] != 64 ||
      input_tensor->dims->data[3] != 1 || input_tensor->bytes != INPUT_BYTES ||
      output_tensor->bytes != 1 || input_tensor->params.scale <= 0 || output_tensor->params.scale <= 0) return false;
  Serial.printf("[MODEL] ready, arena used: %u bytes; heap free: %u bytes\n",
                (unsigned)interpreter->arena_used_bytes(), ESP.getFreeHeap());
  return true;
}

void handle_health() {
  String body = String("{\"ready\":") + (model_ready ? "true" : "false") +
      ",\"device_type\":\"parkly-esp32\",\"model_sha256\":\"" + g_parking_model_sha256 +
      "\",\"input_bytes\":4096,\"arena_bytes\":" + String(TENSOR_ARENA_SIZE) + "}";
  server.send(model_ready ? 200 : 503, "application/json", body);
}

void handle_infer() {
  if (!model_ready) {
    server.send(503, "application/json", "{\"error\":\"MODEL_NOT_READY\"}");
    return;
  }
  if (server.header("Content-Type") != "application/octet-stream") {
    server.send(415, "application/json", "{\"error\":\"EXPECTED_RAW_UINT8\"}");
    return;
  }
  if (server.header("X-Model-Sha256") != g_parking_model_sha256) {
    server.send(409, "application/json", "{\"error\":\"MODEL_MISMATCH\"}");
    return;
  }
  const String request_id = server.header("X-Request-Id");
  const String slot_id = server.header("X-Slot-Id");
  if (!valid_id(request_id) || !valid_id(slot_id)) {
    server.send(400, "application/json", "{\"error\":\"INVALID_REQUEST_OR_SLOT_ID\"}");
    return;
  }
  float threshold = DEFAULT_CAR_THRESHOLD;
  const String threshold_header = server.header("X-Threshold");
  if (threshold_header.length()) {
    char* end = nullptr;
    threshold = strtof(threshold_header.c_str(), &end);
    if (end == threshold_header.c_str() || *end != '\0' || !isfinite(threshold) || threshold < 0 || threshold > 1) {
      server.send(400, "application/json", "{\"error\":\"INVALID_THRESHOLD\"}");
      return;
    }
  }
  if (!raw_complete || raw_invalid || received_bytes != INPUT_BYTES) {
    server.send(400, "application/json", "{\"error\":\"EXPECTED_4096_BYTES\"}");
    return;
  }
  const uint8_t* pixels = pixel_buffer;
  raw_complete = false;
  for (size_t i = 0; i < INPUT_BYTES; i++) {
    // Rescaling /255 is already in the model. Do NOT divide pixels by 255 here.
    int32_t q = (int32_t)roundf(pixels[i] / input_tensor->params.scale) + input_tensor->params.zero_point;
    if (q < -128) q = -128;
    if (q > 127) q = 127;
    input_tensor->data.int8[i] = (int8_t)q;
  }
  uint32_t started = micros();
  if (interpreter->Invoke() != kTfLiteOk) {
    server.send(500, "application/json", "{\"error\":\"INFERENCE_FAILED\"}");
    return;
  }
  float elapsed_ms = (micros() - started) / 1000.0f;
  float score = (output_tensor->data.int8[0] - output_tensor->params.zero_point) * output_tensor->params.scale;
  if (!isfinite(score)) {
    server.send(500, "application/json", "{\"error\":\"INVALID_SCORE\"}");
    return;
  }
  score = constrain(score, 0.0f, 1.0f);
  int label = score >= threshold ? 1 : 0;
  Serial.printf("[INFER] request=%s score=%.6f label=%d latency=%.3f ms\n",
                request_id.c_str(), score, label, elapsed_ms);
  String response = String("{\"request_id\":\"") + request_id + "\",\"slot_id\":\"" + slot_id +
      "\",\"model_sha256\":\"" + g_parking_model_sha256 + "\",\"label\":" + String(label) +
      ",\"car_score\":" + String(score, 8) + ",\"threshold\":" + String(threshold, 8) +
      ",\"latency_ms\":" + String(elapsed_ms, 3) + "}";
  server.send(200, "application/json", response);
}


// Fixed sensor state only; classification is computed from each uploaded image.
// event_id stays 1: clients should call /api/predict for every desired test.
esp_err_t route_sensor(httpd_req_t* req) {
  server.request = req;
  String body = String("{\"distance_cm\":") + String(SIMULATED_DISTANCE_CM, 1) +
      ",\"valid\":true,\"obstacle\":true,\"event_id\":1,\"simulated\":true}";
  server.send(200, "application/json", body);
  return ESP_OK;
}

esp_err_t route_health(httpd_req_t* req) {
  server.request = req;
  handle_health();
  return ESP_OK;
}

esp_err_t route_infer(httpd_req_t* req) {
  server.request = req;
  received_bytes = 0;
  raw_complete = false;
  raw_invalid = true;
  if (req->content_len != INPUT_BYTES) {
    server.send(400, "application/json", "{\"error\":\"EXPECTED_4096_BYTES\"}");
    return ESP_FAIL; // Close rather than retain unread body bytes.
  }
  while (received_bytes < INPUT_BYTES) {
    int count = httpd_req_recv(req, reinterpret_cast<char*>(pixel_buffer) + received_bytes,
                               INPUT_BYTES - received_bytes);
    if (count <= 0) return ESP_FAIL; // Close on timeout or incomplete body.
    received_bytes += count;
  }
  raw_invalid = false;
  raw_complete = true;
  handle_infer();
  return ESP_OK;
}

bool start_http() {
  httpd_config_t config = HTTPD_DEFAULT_CONFIG();
  config.server_port = HTTP_PORT;
  config.stack_size = 8192;
  config.recv_wait_timeout = 5;
  if (httpd_start(&http_server, &config) != ESP_OK) return false;
  httpd_uri_t health = {}, sensor = {}, infer = {};
  health.uri = "/health"; health.method = HTTP_GET; health.handler = route_health;
  sensor.uri = "/sensor"; sensor.method = HTTP_GET; sensor.handler = route_sensor;
  infer.uri = "/infer"; infer.method = HTTP_POST; infer.handler = route_infer;
  if (httpd_register_uri_handler(http_server, &health) != ESP_OK ||
      httpd_register_uri_handler(http_server, &sensor) != ESP_OK ||
      httpd_register_uri_handler(http_server, &infer) != ESP_OK) {
    httpd_stop(http_server);
    http_server = nullptr;
    return false;
  }
  return true;
}

void update_discovery() {
  const String ip = WiFi.localIP().toString();
  if (mdns_ready && mdns_ip == ip) return;
  static uint32_t retry_at = 0;
  if (millis() - retry_at < 3000) return;
  retry_at = millis();
  if (mdns_ready) { MDNS.end(); mdns_ready = false; }
  String suffix = WiFi.macAddress();
  suffix.replace(":", "");
  String hostname = "parkly-" + suffix.substring(6);
  hostname.toLowerCase();
  if (!MDNS.begin(hostname.c_str())) {
    Serial.println("[MDNS] startup failed; retrying");
    return;
  }
  MDNS.addService("parkly", "tcp", HTTP_PORT);
  MDNS.addServiceTxt("parkly", "tcp", "model_sha256", g_parking_model_sha256);
  MDNS.addServiceTxt("parkly", "tcp", "device_type", "parkly-esp32");
  mdns_ip = ip;
  mdns_ready = true;
  Serial.printf("[MDNS] %s.local:%d advertised as _parkly._tcp\n", hostname.c_str(), HTTP_PORT);
}

void setup() {
  Serial.begin(115200);
  Serial.println("[SENSOR] simulated obstacle=true; no HC-SR04 required");
  model_ready = init_model();
  if (!model_ready) Serial.println("[MODEL] initialization failed; /infer returns 503");
  WiFi.mode(WIFI_STA);
  WiFi.setAutoReconnect(true);
  WiFi.begin(WIFI_SSID, WIFI_PASSWORD);
}

void loop() {
  static bool announced = false;
  static uint32_t last_retry = 0;
  if (WiFi.status() == WL_CONNECTED) {
    if (!http_server && millis() - last_retry >= 3000) {
      last_retry = millis();
      if (!start_http()) Serial.println("[HTTP] failed to start; retrying");
    }
    if (http_server) update_discovery();
    if (!announced && http_server) {
      Serial.printf("[HTTP] http://%s:%d; ready=%d\n",
                    WiFi.localIP().toString().c_str(), HTTP_PORT, model_ready);
      announced = true;
    }
  } else {
    if (mdns_ready) { MDNS.end(); mdns_ready = false; }
    announced = false;
    if (millis() - last_retry >= 10000) {
      last_retry = millis();
      Serial.printf("[WIFI] status=%d; requires 2.4 GHz SSID; reconnecting\n", (int)WiFi.status());
      WiFi.reconnect();
    }
  }
  delay(20);
}
